    related: [{"slug":"common-appliance-problems-when-to-call-a-repair-professional","title":"Common Appliance Problems and When to Call a Repair Professional","excerpt":"Most appliance failures announce themselves before they stop working. Here are the symptoms worth acting on, the checks that are safe to do yourself, and the point where a technician should take over.","featured_image":"/images/blog/common-appliance-problems-when-to-call-a-repair-professional.svg","featured_image_alt":"Illustration of a technician checking the inside of a wall oven while a homeowner looks on","published_at":"isoDaysAgo(13, 9)","category":{"slug":"appliance-repair","name":"Appliance Repair"}},{"slug":"refrigerator-not-cooling-common-causes","title":"Refrigerator Not Cooling? Common Causes Homeowners Should Know","excerpt":"A refrigerator that runs but will not cool is usually one of eight things. Start with the checks that cost nothing, then decide whether the sealed system needs a professional.","featured_image":"/images/blog/refrigerator-not-cooling-common-causes.svg","featured_image_alt":"Illustration of an open refrigerator with warm air indicated, a thermometer and a technician's tool bag","published_at":"isoDaysAgo(12, 9)","category":{"slug":"appliance-repair","name":"Appliance Repair"}},{"slug":"warning-signs-your-home-may-have-electrical-problems","title":"Warning Signs Your Home May Have Electrical Problems","excerpt":"Most house fires of electrical origin start with a symptom someone noticed and dismissed. These eight signs are the ones worth acting on — and three need attention today.","featured_image":"/images/blog/warning-signs-your-home-may-have-electrical-problems.svg","featured_image_alt":"Illustration of a homeowner noticing a warm wall outlet with a subtle warning indicator on a home electrical panel","published_at":"isoDaysAgo(10, 9)","category":{"slug":"electrical","name":"Electrical Services"}}],
