    related: [{"slug":"when-should-you-hire-a-licensed-electrician","title":"When Should You Hire a Licensed Electrician?","excerpt":"Some electrical work is a straightforward swap; the rest is licensed work for legal and safety reasons. Here is where the line sits, and how to check a licence properly.","featured_image":"/images/blog/when-should-you-hire-a-licensed-electrician.svg","featured_image_alt":"Illustration of a licensed electrician checking a residential panel while a homeowner reviews a permit document","published_at":"isoDaysAgo(9, 9)","category":{"slug":"electrical","name":"Electrical Services"}},{"slug":"common-causes-of-circuit-breaker-trips","title":"Common Causes of Circuit Breaker Trips","excerpt":"A breaker that trips is doing its job. The question is which of four faults it is protecting you from — and three of them need an electrician rather than a bigger breaker.","featured_image":"/images/blog/common-causes-of-circuit-breaker-trips.svg","featured_image_alt":"Illustration of a homeowner resetting a breaker in a panel with circuit diagrams shown alongside","published_at":"isoDaysAgo(8, 9)","category":{"slug":"electrical","name":"Electrical Services"}},{"slug":"common-appliance-problems-when-to-call-a-repair-professional","title":"Common Appliance Problems and When to Call a Repair Professional","excerpt":"Most appliance failures announce themselves before they stop working. Here are the symptoms worth acting on, the checks that are safe to do yourself, and the point where a technician should take over.","featured_image":"/images/blog/common-appliance-problems-when-to-call-a-repair-professional.svg","featured_image_alt":"Illustration of a technician checking the inside of a wall oven while a homeowner looks on","published_at":"isoDaysAgo(13, 9)","category":{"slug":"appliance-repair","name":"Appliance Repair"}}],
