    related: [{"slug":"warning-signs-you-need-a-plumber","title":"Warning Signs You Need a Plumber (and the Ones You Cannot Ignore)","excerpt":"Most plumbing failures give you days of warning before they become an emergency. Here are the eight symptoms worth acting on, the two that cannot wait, and the checks that are safe to do yourself first.","featured_image":"/images/blog/warning-signs-you-need-a-plumber.svg","featured_image_alt":"Illustration of a kitchen faucet with a drip, a pressure gauge and a wrench","published_at":"isoDaysAgo(7, 9)","category":{"slug":"plumbing","name":"Plumbing"}},{"slug":"common-appliance-problems-when-to-call-a-repair-professional","title":"Common Appliance Problems and When to Call a Repair Professional","excerpt":"Most appliance failures announce themselves before they stop working. Here are the symptoms worth acting on, the checks that are safe to do yourself, and the point where a technician should take over.","featured_image":"/images/blog/common-appliance-problems-when-to-call-a-repair-professional.svg","featured_image_alt":"Illustration of a technician checking the inside of a wall oven while a homeowner looks on","published_at":"isoDaysAgo(13, 9)","category":{"slug":"appliance-repair","name":"Appliance Repair"}},{"slug":"refrigerator-not-cooling-common-causes","title":"Refrigerator Not Cooling? Common Causes Homeowners Should Know","excerpt":"A refrigerator that runs but will not cool is usually one of eight things. Start with the checks that cost nothing, then decide whether the sealed system needs a professional.","featured_image":"/images/blog/refrigerator-not-cooling-common-causes.svg","featured_image_alt":"Illustration of an open refrigerator with warm air indicated, a thermometer and a technician's tool bag","published_at":"isoDaysAgo(12, 9)","category":{"slug":"appliance-repair","name":"Appliance Repair"}}],
